  viewProj: mat4x4<f32>,
  gridCenter: vec4<f32>,
  cameraPos: vec4<f32>,
  worldRight: vec4<f32>,
  worldForward: vec4<f32>,
  minorColor: vec4<f32>,
  majorColor: vec4<f32>,
  xAxisColor: vec4<f32>,
  zAxisColor: vec4<f32>,
  params: vec4<f32>,
  fade: vec4<f32>,
