  let foggedLuma = dot(fogged, LUMA);
  let minLuma = sourceLuma * (1.0 - haze * 0.08);
  fogged = select(fogged, fogged * (minLuma / max(foggedLuma, 0.00001)), foggedLuma < minLuma);
  let skyPixel = rawDepth >= 0.999999 && params.affectSky < 0.5;
